// Clasifica archivos en la estructura actual:
//   RAIZ   → informe PDF principal (00_INFORME_CONSOLIDADO.pdf)
//   LEGAL  → certificados, RUT, ARL, requisitos legales del proveedor
//   ACTAS  → actas, firmas y fotos de respaldo
const body = $input.first().json.body || $input.first().json;
const folderId = body.folderId;
const archivos = body.archivos || [];

const DEST = {
  RAIZ: '00_INFORME_CONSOLIDADO',
  LEGAL: '02_Requisitos_Legales',
  ACTAS: '03_Actas_Firmas'
};

const clasificar = (nombre, mime) => {
  const n = (nombre || '').toLowerCase();
  const m = (mime || '').toLowerCase();
  if (/\b(certificad|requisit|legal|cumplimient|ley|arl|rut|camara|comerc|poliza|contrato)\b/.test(n)) return DEST.LEGAL;
  if (/\b(acta|firma|recibid|entrega)\b/.test(n)) return DEST.ACTAS;
  if (/\b(informe|reporte|consolidad)\b/.test(n)) return DEST.RAIZ;
  if (m.startsWith('image/') || /\.(jpg|jpeg|png|heic|webp|gif)$/i.test(n)) return DEST.ACTAS;
  if (m === 'application/pdf' || n.endsWith('.pdf')) return DEST.RAIZ;
  return DEST.ACTAS;
};

return archivos.map((a, i) => {
  const destino = a.subcarpeta || clasificar(a.nombre, a.mime_type);
  const esRaiz = destino === DEST.RAIZ;
  return {
    json: {
      index: i,
      folderId,
      subcarpeta: destino,
      esRaiz,
      subcarpetaBuscar: esRaiz ? DEST.ACTAS : destino,
      fileName: a.nombre,
      mimeType: a.mime_type || 'application/octet-stream'
    },
    binary: {
      data: {
        data: a.base64,
        mimeType: a.mime_type || 'application/octet-stream',
        fileName: a.nombre
      }
    }
  };
});

// Si es raíz → folderId directo. Si no, busca la subcarpeta; si no existe
// (típico de jornadas históricas), hace fallback a raíz.
const input = $input.first();
let subcarpetaId;
let destinoReal = input.json.subcarpeta;
if (input.json.esRaiz) {
  subcarpetaId = input.json.folderId;
  destinoReal = 'RAIZ_JORNADA';
} else {
  const busqueda = $('Buscar subcarpeta').first()?.json || {};
  if (busqueda.id) {
    subcarpetaId = busqueda.id;
  } else {
    subcarpetaId = input.json.folderId;
    destinoReal = 'RAIZ_JORNADA (fallback: ' + input.json.subcarpeta + ' no existe)';
  }
}
return [{
  json: { ...input.json, subcarpetaId, destinoReal },
  binary: input.binary
}];

// Agrega todos los uploads en un solo item de respuesta.
const items = $input.all();
const archivos = items.map(it => ({
  nombre: it.json.name || it.json.fileName,
  url: it.json.webViewLink || it.json.webContentLink || `https://drive.google.com/file/d/${it.json.id}/view`,
  file_id: it.json.id,
  subcarpeta: it.json.subcarpeta || null
}));
return [{ json: { archivos, cantidad: archivos.length } }];
